91	// ReconcileDisconnectedMetadataBranch detects and repairs disconnected local/remote
92	// entire/checkpoints/v1 branches. Disconnected means no common ancestor, which
93	// only happens due to the empty-orphan bug. Diverged (shared ancestor) is normal
94	// and handled by the push path's tree merge.
95	//
96	// Repair strategy: cherry-pick local commits onto remote tip, preserving all data.
97	// Checkpoint shards use unique paths (<id[:2]>/<id[2:]>/), so cherry-picks always
98	// apply cleanly.
99	//
100	// Progress messages are written to w (typically os.Stderr for hooks or
101	// cmd.ErrOrStderr() for commands).
102	// The remote ref can be either a remote-tracking ref or a temporary fetched ref.
103	func ReconcileDisconnectedMetadataBranch(
104		ctx context.Context,
105		repo *git.Repository,
106		remoteRefName plumbing.ReferenceName,
107		w io.Writer,
108	) error {
109		refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
110	
111		// Check local branch
112		localRef, err := repo.Reference(refName, true)
113		if errors.Is(err, plumbing.ErrReferenceNotFound) {
114			return nil // No local branch — nothing to reconcile
115		}
116		if err != nil {
117			return fmt.Errorf("failed to check local metadata branch: %w", err)
118		}
119	
120		// Check remote-tracking branch
121		remoteRef, err := repo.Reference(remoteRefName, true)
122		if errors.Is(err, plumbing.ErrReferenceNotFound) {
123			return nil // No remote branch — nothing to reconcile
124		}
125		if err != nil {
126			return fmt.Errorf("failed to check remote metadata branch: %w", err)
127		}
128	
129		localHash := localRef.Hash()
130		remoteHash := remoteRef.Hash()
131	
132		// Same hash — nothing to do
133		if localHash == remoteHash {
134			return nil
135		}
136	
137		// Check if disconnected using git merge-base
138		repoPath, err := getRepoPath(repo)
139		if err != nil {
140			return err
141		}
142	
143		disconnected, err := isDisconnected(ctx, repoPath, localHash.String(), remoteHash.String())
144		if err != nil {
145			return fmt.Errorf("failed to check metadata branch ancestry: %w", err)
146		}
147		if !disconnected {
148			// Shared ancestry (diverged or ancestor) — not our problem
149			return nil
150		}
151	
152		// Disconnected — cherry-pick local commits onto remote tip
153		fmt.Fprintln(w, "[entire] Detected disconnected session metadata (local and remote share no common ancestor)")
154	
155		// Collect local commits oldest-first
156		localCommits, err := collectCommitChain(repo, localHash)
157		if err != nil {
158			return fmt.Errorf("failed to collect local commits: %w", err)
159		}
160	
161		// Filter out empty-tree commits (the orphan bug commit)
162		var dataCommits []*object.Commit
163		for _, c := range localCommits {
164			tree, treeErr := c.Tree()
165			if treeErr != nil {
166				return fmt.Errorf("failed to read tree for commit %s: %w", c.Hash.String()[:7], treeErr)
167			}
168			if len(tree.Entries) > 0 {
169				dataCommits = append(dataCommits, c)
170			}
171		}
172	
173		if len(dataCommits) == 0 {
174			// Local only had empty orphan — just point to remote
175			ref := plumbing.NewHashReference(refName, remoteHash)
176			if err := repo.Storer.SetReference(ref); err != nil {
177				return fmt.Errorf("failed to reset metadata branch to remote: %w", err)
178			}
179			fmt.Fprintln(w, "[entire] Done — local had no checkpoint data, reset to remote")
180			return nil
181		}
182	
183		fmt.Fprintf(w, "[entire] Cherry-picking %d local checkpoint(s) onto remote...\n", len(dataCommits))
184	
185		newTip, err := cherryPickOnto(ctx, repo, remoteHash, dataCommits)
186		if err != nil {
187			return fmt.Errorf("failed to cherry-pick local commits onto remote: %w", err)
188		}
189	
190		// Update local branch ref
191		ref := plumbing.NewHashReference(refName, newTip)
192		if err := repo.Storer.SetReference(ref); err != nil {
193			return fmt.Errorf("failed to update metadata branch: %w", err)
194		}
195	
196		fmt.Fprintln(w, "[entire] Done — all local and remote checkpoints preserved")
197		return nil
198	}
