200	// v2DoctorTmpRef is the temporary ref used by doctor to fetch and compare the remote v2 /main.
201	// Uses the refs/entire-fetch-tmp/ namespace consistent with checkpoint_remote.go.
202	const v2DoctorTmpRef = "refs/entire-fetch-tmp/doctor-v2-main"
203	
204	// IsV2MainDisconnected checks whether the local v2 /main ref and the remote
205	// v2 /main ref exist but share no common ancestor. Uses git ls-remote to
206	// discover the remote ref (custom refs don't have remote-tracking refs).
207	//
208	// remote is the git remote name, URL, or local path to check against.
209	// Returns (false, nil) if either ref doesn't exist or they share ancestry.
210	func IsV2MainDisconnected(ctx context.Context, repo *git.Repository, remote string) (bool, error) {
211		refName := plumbing.ReferenceName(paths.V2MainRefName)
212	
213		localRef, err := repo.Reference(refName, true)
214		if errors.Is(err, plumbing.ErrReferenceNotFound) {
215			return false, nil
216		}
217		if err != nil {
218			return false, fmt.Errorf("failed to check local v2 /main ref: %w", err)
219		}
220	
221		repoPath, err := getRepoPath(repo)
222		if err != nil {
223			return false, err
224		}
225	
226		remoteHash, err := lsRemoteRef(ctx, repoPath, remote, paths.V2MainRefName)
227		if err != nil {
228			return false, fmt.Errorf("failed to ls-remote v2 /main: %w", err)
229		}
230		if remoteHash == plumbing.ZeroHash {
231			return false, nil // Remote doesn't have the ref
232		}
233	
234		if localRef.Hash() == remoteHash {
235			return false, nil
236		}
237	
238		// Fetch remote ref to temporary local ref for merge-base check.
239		// Use the fetched hash (not ls-remote hash) since the remote may have advanced.
240		if fetchErr := fetchRefToTemp(ctx, repoPath, remote, paths.V2MainRefName, v2DoctorTmpRef); fetchErr != nil {
241			return false, fmt.Errorf("failed to fetch remote v2 /main: %w", fetchErr)
242		}
243		defer cleanupTmpRef(repo)
244	
245		fetchedHash, err := resolveRefHash(repo, v2DoctorTmpRef)
246		if err != nil {
247			return false, fmt.Errorf("failed to read fetched v2 /main ref: %w", err)
248		}
249	
250		if localRef.Hash() == fetchedHash {
251			return false, nil
252		}
253	
254		return isDisconnected(ctx, repoPath, localRef.Hash().String(), fetchedHash.String())
255	}
