390	// fetchRefToTemp fetches a remote ref to a temporary local ref for comparison.
391	func fetchRefToTemp(ctx context.Context, repoPath, remoteName, srcRef, dstRef string) error {
392		ctx, cancel := context.WithTimeout(ctx, 30*time.Second)
393		defer cancel()
394	
395		fetchTarget, err := remote.ResolveFetchTarget(ctx, remoteName)
396		if err != nil {
397			return fmt.Errorf("resolve fetch target for doctor v2 fetch: %w", err)
398		}
399	
400		refspec := fmt.Sprintf("+%s:%s", srcRef, dstRef)
401		output, err := remote.Fetch(ctx, remote.FetchOptions{
402			Remote:   fetchTarget,
403			RefSpecs: []string{refspec},
404			NoTags:   true,
405			Dir:      repoPath,
406		})
407		if err != nil {
408			redactedURL := remote.RedactURL(fetchTarget)
409			msg := strings.TrimSpace(strings.ReplaceAll(string(output), fetchTarget, redactedURL))
410			if msg != "" {
411				return fmt.Errorf("git fetch %s failed: %s: %w", redactedURL, msg, err)
412			}
413			return fmt.Errorf("git fetch %s failed: %w", redactedURL, err)
414		}
415		return nil
416	}
