418	// resolveRefHash reads the commit hash that a ref points to.
419	func resolveRefHash(repo *git.Repository, refName string) (plumbing.Hash, error) {
420		ref, err := repo.Reference(plumbing.ReferenceName(refName), true)
421		if err != nil {
422			return plumbing.ZeroHash, fmt.Errorf("ref %s not found: %w", refName, err)
423		}
424		return ref.Hash(), nil
425	}
