427	// cleanupTmpRef deletes the temporary ref used by doctor checks.
428	func cleanupTmpRef(repo *git.Repository) {
429		_ = repo.Storer.RemoveReference(plumbing.ReferenceName(v2DoctorTmpRef)) //nolint:errcheck // best-effort cleanup
430	}
