432	// isDisconnected checks if two commits have no common ancestor using git merge-base.
433	// Returns (true, nil) if disconnected, (false, nil) if they share ancestry,
434	// or (false, error) if git merge-base failed for another reason.
435	//
436	// git merge-base exit codes:
437	//   - 0: common ancestor found (shared ancestry)
438	//   - 1: no common ancestor (disconnected)
439	//   - 128+: error (corrupt repo, invalid hash, etc.)
440	func isDisconnected(ctx context.Context, repoPath, hashA, hashB string) (bool, error) {
441		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
442		defer cancel()
443		cmd := exec.CommandContext(ctx, "git", "merge-base", hashA, hashB)
444		cmd.Dir = repoPath
445		if err := cmd.Run(); err != nil {
446			var exitErr *exec.ExitError
447			if errors.As(err, &exitErr) && exitErr.ExitCode() == 1 {
448				return true, nil // No common ancestor — disconnected
449			}
450			return false, fmt.Errorf("git merge-base failed: %w", err)
451		}
452		return false, nil // Shared ancestry
453	}
