455	// collectCommitChain walks from tip to root following first parent, returns oldest-first.
456	func collectCommitChain(repo *git.Repository, tip plumbing.Hash) ([]*object.Commit, error) {
457		var chain []*object.Commit
458		current := tip
459	
460		reachedRoot := false
461		for range MaxCommitTraversalDepth {
462			commit, err := repo.CommitObject(current)
463			if err != nil {
464				return nil, fmt.Errorf("failed to get commit %s: %w", current, err)
465			}
466			chain = append(chain, commit)
467	
468			if len(commit.ParentHashes) == 0 {
469				reachedRoot = true
470				break
471			}
472			current = commit.ParentHashes[0]
473		}
474	
475		if !reachedRoot {
476			return nil, fmt.Errorf("commit chain exceeded %d commits without reaching root; aborting reconciliation", MaxCommitTraversalDepth)
477		}
478	
479		// Reverse to oldest-first
480		for i, j := 0, len(chain)-1; i < j; i, j = i+1, j-1 {
481			chain[i], chain[j] = chain[j], chain[i]
482		}
483	
484		return chain, nil
485	}
