487	// cherryPickOnto applies each commit's delta onto base, building a linear chain.
488	// For each commit, it computes the full diff from its parent (additions, modifications,
489	// and deletions), then applies that delta onto the current tip's tree.
490	func cherryPickOnto(ctx context.Context, repo *git.Repository, base plumbing.Hash, commits []*object.Commit) (plumbing.Hash, error) {
491		currentTip := base
492	
493		for _, commit := range commits {
494			// Get the commit's tree entries
495			commitTree, err := commit.Tree()
496			if err != nil {
497				return plumbing.ZeroHash, fmt.Errorf("failed to get tree for commit %s: %w", commit.Hash, err)
498			}
499	
500			commitEntries := make(map[string]object.TreeEntry)
501			if err := checkpoint.FlattenTree(repo, commitTree, "", commitEntries); err != nil {
502				return plumbing.ZeroHash, fmt.Errorf("failed to flatten commit tree: %w", err)
503			}
504	
505			// Get parent's tree entries (empty if root commit)
506			parentEntries := make(map[string]object.TreeEntry)
507			if len(commit.ParentHashes) > 0 {
508				parentCommit, pErr := repo.CommitObject(commit.ParentHashes[0])
509				if pErr != nil {
510					return plumbing.ZeroHash, fmt.Errorf("failed to get parent commit %s: %w", commit.ParentHashes[0], pErr)
511				}
512				parentTree, ptErr := parentCommit.Tree()
513				if ptErr != nil {
514					return plumbing.ZeroHash, fmt.Errorf("failed to get parent tree for commit %s: %w", commit.ParentHashes[0], ptErr)
515				}
516				if err := checkpoint.FlattenTree(repo, parentTree, "", parentEntries); err != nil {
517					return plumbing.ZeroHash, fmt.Errorf("failed to flatten parent tree for commit %s: %w", commit.ParentHashes[0], err)
518				}
519			}
520	
521			// Compute full delta: additions, modifications, and deletions
522			added := make(map[string]object.TreeEntry)
523			for path, entry := range commitEntries {
524				parentEntry, exists := parentEntries[path]
525				if !exists || parentEntry.Hash != entry.Hash {
526					added[path] = entry // New or modified
527				}
528			}
529			var deleted []string
530			for path := range parentEntries {
531				if _, exists := commitEntries[path]; !exists {
532					deleted = append(deleted, path) // Removed in this commit
533				}
534			}
535	
536			if len(added) == 0 && len(deleted) == 0 {
537				continue // Skip no-op commits
538			}
539	
540			// Get current tip's tree and apply delta
541			tipCommit, err := repo.CommitObject(currentTip)
542			if err != nil {
543				return plumbing.ZeroHash, fmt.Errorf("failed to get tip commit: %w", err)
544			}
545			tipTree, err := tipCommit.Tree()
546			if err != nil {
547				return plumbing.ZeroHash, fmt.Errorf("failed to get tip tree: %w", err)
548			}
549	
550			mergedEntries := make(map[string]object.TreeEntry)
551			if err := checkpoint.FlattenTree(repo, tipTree, "", mergedEntries); err != nil {
552				return plumbing.ZeroHash, fmt.Errorf("failed to flatten tip tree: %w", err)
553			}
554			for path, entry := range added {
555				mergedEntries[path] = entry
556			}
557			for _, path := range deleted {
558				delete(mergedEntries, path)
559			}
560	
561			mergedTreeHash, err := checkpoint.BuildTreeFromEntries(ctx, repo, mergedEntries)
562			if err != nil {
563				return plumbing.ZeroHash, fmt.Errorf("failed to build merged tree: %w", err)
564			}
565	
566			// Create new commit on top of current tip, preserving original message/author
567			newHash, err := createCherryPickCommit(ctx, repo, mergedTreeHash, currentTip, commit)
568			if err != nil {
569				return plumbing.ZeroHash, fmt.Errorf("failed to create cherry-pick commit: %w", err)
570			}
571	
572			currentTip = newHash
573		}
574	
575		return currentTip, nil
576	}
