578	// createCherryPickCommit creates a new commit on top of parent, preserving the
579	// original commit's message and author.
580	func createCherryPickCommit(ctx context.Context, repo *git.Repository, treeHash, parent plumbing.Hash, original *object.Commit) (plumbing.Hash, error) {
581		committerName, committerEmail := GetGitAuthorFromRepo(repo)
582		now := time.Now()
583	
584		commit := &object.Commit{
585			TreeHash:     treeHash,
586			ParentHashes: []plumbing.Hash{parent},
587			Author:       original.Author,
588			Committer: object.Signature{
589				Name:  committerName,
590				Email: committerEmail,
591				When:  now,
592			},
593			Message: original.Message,
594		}
595	
596		checkpoint.SignCommitBestEffort(ctx, commit)
597	
598		obj := repo.Storer.NewEncodedObject()
599		if err := commit.Encode(obj); err != nil {
600			return plumbing.ZeroHash, fmt.Errorf("failed to encode commit: %w", err)
601		}
602	
603		hash, err := repo.Storer.SetEncodedObject(obj)
604		if err != nil {
605			return plumbing.ZeroHash, fmt.Errorf("failed to store commit: %w", err)
606		}
607	
608		return hash, nil
609	}
