611	// getRepoPath returns the filesystem path for the repository's worktree.
612	func getRepoPath(repo *git.Repository) (string, error) {
613		wt, err := repo.Worktree()
614		if err != nil {
615			return "", fmt.Errorf("failed to get worktree: %w", err)
616		}
617		return wt.Filesystem.Root(), nil
618	}
