112	// printCheckpointRemoteHint prints a hint when a push to a checkpoint URL fails.
113	// Only prints when the target is a URL (not the user's default remote).
114	func printCheckpointRemoteHint(target string) {
115		if !remote.IsURL(target) {
116			return
117		}
118		fmt.Fprintln(os.Stderr, "[entire] A checkpoint remote is configured in Entire settings (.entire/settings.json or .entire/settings.local.json) but could not be reached.")
119		fmt.Fprintln(os.Stderr, "[entire] Checkpoints are saved locally but not synced. Ensure you have access to the checkpoint remote.")
120	}
