122	// settingsHintOnce ensures the settings commit hint prints at most once per process.
123	var settingsHintOnce sync.Once
124	
125	// checkpointsV2MigrationHintOnce ensures the checkpoints v2 migration hint prints at most once per process.
126	var checkpointsV2MigrationHintOnce sync.Once
127	
128	// printSettingsCommitHint prints a hint after a successful checkpoint remote push
129	// when the committed .entire/settings.json does not contain a checkpoint_remote config.
130	// entire.io discovers the external checkpoint repo by reading the committed project
131	// settings, so the checkpoint_remote must be present in HEAD:.entire/settings.json
132	// (not just in settings.local.json or uncommitted local changes).
133	// Uses sync.Once to avoid duplicates when multiple branches/refs are pushed in a
134	// single pre-push invocation.
135	func printSettingsCommitHint(ctx context.Context, target string) {
136		if !remote.IsURL(target) {
137			return
138		}
139		settingsHintOnce.Do(func() {
140			if isCheckpointRemoteCommitted(ctx) {
141				return
142			}
143			fmt.Fprintln(os.Stderr, "[entire] Note: Checkpoints were pushed to a separate checkpoint remote, but .entire/settings.json does not contain checkpoint_remote in the latest commit. entire.io will not be able to discover these checkpoints until checkpoint_remote is committed and pushed in .entire/settings.json.")
144		})
145	}
