147	// printCheckpointsV2MigrationHint prints a hint when the committed project
148	// settings enable checkpoints_version: 2 AND there are v1 checkpoints that have
149	// not yet been mirrored into v2. Suppressed when v2 already has every v1
150	// checkpoint (nothing to migrate) so the hint does not become noise once the
151	// migration is done.
152	func printCheckpointsV2MigrationHint(ctx context.Context) {
153		checkpointsV2MigrationHintOnce.Do(func() {
154			if !isCheckpointsVersion2Committed(ctx) {
155				return
156			}
157			if !hasUnmigratedV1Checkpoints(ctx) {
158				return
159			}
160			fmt.Fprintln(os.Stderr, "[entire] Note: .entire/settings.json sets checkpoints_version: 2. Run 'entire migrate --checkpoints v2' to migrate existing checkpoints to v2.")
161			fmt.Fprintln(os.Stderr, "[entire] Use 'entire migrate --checkpoints v2 --force' to rewrite all checkpoints in v2.")
162		})
163	}
