165	// hasUnmigratedV1Checkpoints reports whether any v1 checkpoint has no matching
166	// entry in v2. Any failure opening the repo or listing either store is treated
167	// as "no migration needed" so we stay silent instead of printing a speculative
168	// hint — the hint is advisory and should never be the reason a push gets noisy.
169	func hasUnmigratedV1Checkpoints(ctx context.Context) bool {
170		repo, err := OpenRepository(ctx)
171		if err != nil {
172			return false
173		}
174		v1List, err := checkpoint.NewGitStore(repo).ListCommitted(ctx)
175		if err != nil || len(v1List) == 0 {
176			return false
177		}
178		v2List, err := checkpoint.NewV2GitStore(repo, "").ListCommitted(ctx)
179		if err != nil {
180			return false
181		}
182		v2Set := make(map[string]struct{}, len(v2List))
183		for _, info := range v2List {
184			v2Set[info.CheckpointID.String()] = struct{}{}
185		}
186		for _, info := range v1List {
187			if _, ok := v2Set[info.CheckpointID.String()]; !ok {
188				return true
189			}
190		}
191		return false
192	}
