212	// isCheckpointsVersion2Committed returns true if the committed .entire/settings.json
213	// at HEAD sets checkpoints_version to 2.
214	func isCheckpointsVersion2Committed(ctx context.Context) bool {
215		cmd := exec.CommandContext(ctx, "git", "show", "HEAD:.entire/settings.json")
216		output, err := cmd.Output()
217		if err != nil {
218			return false
219		}
220		committed, err := settings.LoadFromBytes(output)
221		if err != nil {
222			return false
223		}
224		return committed.CheckpointsVersion() == 2
