227	// pushResult describes what happened during a push attempt.
228	type pushResult struct {
229		// upToDate is true when the remote already had all commits (nothing transferred).
230		upToDate bool
231	}
232	
233	// parsePushResult checks git push --porcelain output for ref status flags.
234	// In porcelain mode, each ref gets a tab-delimited status line:
235	//
236	//	<flag>\t<from>:<to>\t<summary>
237	//
238	// where flag '=' means the ref was already up-to-date. This is locale-independent,
239	// unlike the human-readable "Everything up-to-date" message.
240	func parsePushResult(output string) pushResult {
241		for _, line := range strings.Split(output, "\n") {
242			if strings.HasPrefix(line, "=\t") {
243				return pushResult{upToDate: true}
244			}
245		}
246		return pushResult{upToDate: false}
247	}
248	
249	// finishPush stops the progress dots and prints "already up-to-date" or "done"
250	// depending on the push result. Only prints the settings commit hint when new
251	// content was actually pushed.
252	func finishPush(ctx context.Context, stop func(string), result pushResult, target string) {
253		if result.upToDate {
254			stop(" already up-to-date")
255		} else {
256			stop(" done")
257			printSettingsCommitHint(ctx, target)
258		}
259		printCheckpointsV2MigrationHint(ctx)
260	}
