262	// tryPushSessionsCommon attempts to push the sessions branch.
263	func tryPushSessionsCommon(ctx context.Context, remoteName, branchName string) (pushResult, error) {
264		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
265		defer cancel()
266	
267		result, err := remote.Push(ctx, remoteName, branchName)
268		outputStr := result.Output
269		if err != nil {
270			if strings.Contains(outputStr, "non-fast-forward") ||
271				strings.Contains(outputStr, "rejected") {
272				return pushResult{}, errors.New("non-fast-forward")
273			}
274			return pushResult{}, fmt.Errorf("push failed: %s", outputStr)
275		}
276	
277		return parsePushResult(outputStr), nil
278	}
