280	// fetchAndRebaseSessionsCommon fetches remote sessions and rebases local commits
281	// on top of the remote tip. Since checkpoint shards use unique paths, rebases
282	// always apply cleanly.
283	// The target can be a remote name or a URL.
284	func fetchAndRebaseSessionsCommon(ctx context.Context, target, branchName string) error {
285		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
286		defer cancel()
287	
288		fetchTarget, err := remote.ResolveFetchTarget(ctx, target)
289		if err != nil {
290			return fmt.Errorf("resolve fetch target: %w", err)
291		}
292	
293		// Determine fetch refspec. When the resolved fetch target is a URL, use a
294		// temp ref; when it's still a remote name, use the standard remote-tracking
295		// ref.
296		var fetchedRefName plumbing.ReferenceName
297		var refSpec string
298		usedTempRef := remote.IsURL(fetchTarget)
299		if usedTempRef {
300			tmpRef := "refs/entire-fetch-tmp/" + branchName
301			refSpec = fmt.Sprintf("+refs/heads/%s:%s", branchName, tmpRef)
302			fetchedRefName = plumbing.ReferenceName(tmpRef)
303		} else {
304			refSpec = fmt.Sprintf("+refs/heads/%s:refs/remotes/%s/%s", branchName, target, branchName)
305			fetchedRefName = plumbing.NewRemoteReferenceName(target, branchName)
306		}
307	
308		// Use git CLI for fetch (go-git's fetch can be tricky with auth).
309		// Use --filter=blob:none for a partial fetch that downloads only commits
310		// and trees, skipping blobs. The merge only needs the tree structure to
311		// combine entries; blobs are already local or fetched on demand.
312		if output, fetchErr := remote.Fetch(ctx, remote.FetchOptions{
313			Remote:   fetchTarget,
314			RefSpecs: []string{refSpec},
315			NoTags:   true,
316		}); fetchErr != nil {
317			return fmt.Errorf("fetch failed: %s", output)
318		}
319	
320		repo, err := OpenRepository(ctx)
321		if err != nil {
322			return fmt.Errorf("failed to open git repository: %w", err)
323		}
324	
325		// Reconcile disconnected metadata branches before rebasing.
326		// The fetch above updated the remote-tracking ref, so reconciliation
327		// can compare fresh local vs remote. If disconnected (empty-orphan bug),
328		// this cherry-picks local commits onto remote tip, updating the local ref.
329		// If reconciliation fails, abort — proceeding to rebase on disconnected
330		// branches would silently combine unrelated histories.
331		if reconcileErr := ReconcileDisconnectedMetadataBranch(ctx, repo, fetchedRefName, os.Stderr); reconcileErr != nil {
332			return fmt.Errorf("metadata reconciliation failed: %w", reconcileErr)
333		}
334	
335		// Get local branch (re-read after potential reconciliation update)
336		localRef, err := repo.Reference(plumbing.NewBranchReferenceName(branchName), true)
337		if err != nil {
338			return fmt.Errorf("failed to get local ref: %w", err)
339		}
340	
341		// Get fetched ref (remote-tracking or temp ref, updated by the fetch above)
342		remoteRef, err := repo.Reference(fetchedRefName, true)
343		if err != nil {
344			return fmt.Errorf("failed to get remote ref: %w", err)
345		}
346	
347		// If local is already at or behind remote, fast-forward
348		if localRef.Hash() == remoteRef.Hash() {
349			return nil
350		}
351	
352		// Find merge base
353		repoPath, err := getRepoPath(repo)
354		if err != nil {
355			return fmt.Errorf("failed to get repo path: %w", err)
356		}
357		mergeBase, err := getMergeBase(ctx, repoPath, localRef.Hash().String(), remoteRef.Hash().String())
358		if err != nil {
359			return fmt.Errorf("failed to find merge base: %w", err)
360		}
361	
362		// If local is ancestor of remote (merge base == local), fast-forward to remote
363		if mergeBase == localRef.Hash() {
364			ref := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), remoteRef.Hash())
365			if err := repo.Storer.SetReference(ref); err != nil {
366				return fmt.Errorf("failed to fast-forward branch ref: %w", err)
367			}
368			if usedTempRef {
369				_ = repo.Storer.RemoveReference(fetchedRefName) //nolint:errcheck // cleanup is best-effort
370			}
371			return nil
372		}
373	
374		// Collect commits reachable from local but not from remote and cherry-pick
375		// them onto the remote tip. This preserves local-only commits even when the
376		// local metadata branch already contains old merge commits, while avoiding
377		// replaying shared ancestors older than the true merge-base.
378		localCommits, err := collectCommitsSince(ctx, repo, repoPath, localRef.Hash(), remoteRef.Hash())
379		if err != nil {
380			return fmt.Errorf("failed to collect local commits: %w", err)
381		}
382	
383		if len(localCommits) == 0 {
384			// No local-only commits — just point to remote
385			ref := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), remoteRef.Hash())
386			if err := repo.Storer.SetReference(ref); err != nil {
387				return fmt.Errorf("failed to update branch ref: %w", err)
388			}
389			if usedTempRef {
390				_ = repo.Storer.RemoveReference(fetchedRefName) //nolint:errcheck // cleanup is best-effort
391			}
392			return nil
393		}
394	
395		newTip, err := cherryPickOnto(ctx, repo, remoteRef.Hash(), localCommits)
396		if err != nil {
397			return fmt.Errorf("failed to rebase local commits onto remote: %w", err)
398		}
399	
400		// Update branch ref
401		newRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), newTip)
402		if err := repo.Storer.SetReference(newRef); err != nil {
403			return fmt.Errorf("failed to update branch ref: %w", err)
404		}
405	
406		// Clean up temp ref if we used one (best-effort, not critical if it fails)
407		if usedTempRef {
408			_ = repo.Storer.RemoveReference(fetchedRefName) //nolint:errcheck // cleanup is best-effort
409		}
410	
411		return nil
412	}
413	
414	// getMergeBase returns the merge base hash of two commits, or an error if they
415	// have no common ancestor.
416	func getMergeBase(ctx context.Context, repoPath, hashA, hashB string) (plumbing.Hash, error) {
417		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
418		defer cancel()
419	
420		cmd := exec.CommandContext(ctx, "git", "merge-base", hashA, hashB)
421		cmd.Dir = repoPath
422		output, err := cmd.Output()
423		if err != nil {
424			return plumbing.ZeroHash, fmt.Errorf("git merge-base failed: %w", err)
425		}
426	
427		return plumbing.NewHash(strings.TrimSpace(string(output))), nil
428	}
429	
430	// collectCommitsSince returns non-merge commits reachable from tip but not from
431	// exclude, ordered oldest-first in topological order.
432	func collectCommitsSince(ctx context.Context, repo *git.Repository, repoPath string, tip, exclude plumbing.Hash) ([]*object.Commit, error) {
433		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
434		defer cancel()
435	
436		// cherryPickOnto computes each commit's delta against its first parent, so
437		// replaying merge commits would incorrectly re-apply changes that arrived via
438		// non-first-parent history. Limit the replay set to non-merge commits.
439		cmd := exec.CommandContext(ctx, "git", "rev-list", "--reverse", "--topo-order", "--no-merges", exclude.String()+".."+tip.String())
440		cmd.Dir = repoPath
441		output, err := cmd.Output()
442		if err != nil {
443			return nil, fmt.Errorf("git rev-list failed: %w", err)
444		}
445	
446		lines := strings.Fields(string(output))
447		if len(lines) > MaxCommitTraversalDepth {
448			return nil, fmt.Errorf("commit chain exceeded %d commits; aborting rebase", MaxCommitTraversalDepth)
449		}
450	
451		commits := make([]*object.Commit, 0, len(lines))
452		for _, line := range lines {
453			hash := plumbing.NewHash(line)
454			commit, commitErr := repo.CommitObject(hash)
455			if commitErr != nil {
456				return nil, fmt.Errorf("failed to get commit %s: %w", hash, commitErr)
457			}
458			if len(commit.ParentHashes) > 1 {
459				continue
460			}
461			commits = append(commits, commit)
462		}
463	
464		return commits, nil
465	}
