158	// newCommand creates an exec.Cmd for a git operation that may need
159	// checkpoint token authentication. If ENTIRE_CHECKPOINT_TOKEN is set:
160	//   - if the target in args is (or resolves to) an SSH remote, the target is
161	//     rewritten in the args to the equivalent HTTPS URL so git uses HTTP
162	//     transport and our injected Authorization header applies;
163	//   - a Basic auth token is then injected via GIT_CONFIG_COUNT/GIT_CONFIG_KEY_*/
164	//     GIT_CONFIG_VALUE_* environment variables.
165	//
166	// If rewriting fails (unparseable URL, missing owner/repo) the command runs
167	// unmodified and a one-shot warning is printed.
168	// For empty/unset tokens, the command is returned unmodified.
169	//
170	// The remote is extracted from args by skipping the git subcommand and any flags
171	// (arguments starting with "-"). For example, in
172	// ["push", "--no-verify", "origin", "main"], the remote is "origin".
173	func newCommand(ctx context.Context, args ...string) *exec.Cmd {
174		token := strings.TrimSpace(os.Getenv(CheckpointTokenEnvVar))
175	
176		mkCmd := func(finalArgs []string) *exec.Cmd {
177			c := exec.CommandContext(ctx, "git", finalArgs...)
178			c.Stdin = nil // Disconnect stdin to prevent hanging in hook context
179			return c
180		}
181	
182		if token == "" {
183			return mkCmd(args)
184		}
185	
186		if !isValidToken(token) {
187			fmt.Fprintf(os.Stderr, "[entire] Warning: %s contains invalid characters (CR, LF, or other control chars) — token ignored\n", CheckpointTokenEnvVar)
188			return mkCmd(args)
189		}
190	
191		target := extractRemoteFromArgs(args)
192		if target == "" {
193			return mkCmd(args)
194		}
195	
196		newTarget, protocol := resolveTargetForTokenAuth(ctx, target)
197		if newTarget != target {
198			args = replaceFirstPositional(args, newTarget)
199		}
200	
201		cmd := mkCmd(args)
202	
203		switch protocol {
204		case ProtocolSSH:
205			sshTokenWarningOnce.Do(func() {
206				fmt.Fprintf(os.Stderr, "[entire] Warning: %s is set but remote uses SSH — token ignored for SSH remotes\n", CheckpointTokenEnvVar)
207			})
208			return cmd
209		case ProtocolHTTPS:
210			cmd.Env = appendCheckpointTokenEnv(os.Environ(), token)
211			return cmd
212		default:
213			// Unknown protocol (e.g., local path, or resolution failed) — don't inject
214			return cmd
215		}
216	}
