218	// resolveTargetForTokenAuth resolves a git target (remote name or URL) to its
219	// effective protocol, rewriting SSH targets to the equivalent HTTPS URL so
220	// token-based auth can be applied. Returns the (possibly rewritten) target and
221	// its final protocol. Protocol is "" when resolution fails (local path,
222	// nonexistent remote, unparseable URL).
223	//
224	// This is only meaningful when ENTIRE_CHECKPOINT_TOKEN is set; callers gate on
225	// that themselves.
226	func resolveTargetForTokenAuth(ctx context.Context, target string) (string, string) {
227		if target == "" || isLocalPath(target) {
228			return target, ""
229		}
230	
231		rawURL := target
232		if !IsURL(target) {
233			var err error
234			rawURL, err = GetRemoteURL(ctx, target)
235			if err != nil {
236				return target, ""
237			}
238		}
239	
240		info, err := ParseURL(rawURL)
241		if err != nil {
242			return target, ""
243		}
244	
245		if info.Protocol == ProtocolSSH {
246			if httpsURL, ok := deriveTokenOriginURL(rawURL); ok {
247				return httpsURL, ProtocolHTTPS
248			}
249			return target, ProtocolSSH
250		}
251	
252		return target, info.Protocol
253	}
