255	// replaceFirstPositional returns a copy of args with the first non-flag
256	// argument after args[0] (the git subcommand) replaced by newTarget. Callers
257	// use this to rewrite a remote name/URL after resolution without mutating the
258	// original slice.
259	func replaceFirstPositional(args []string, newTarget string) []string {
260		out := make([]string, len(args))
261		copy(out, args)
262		for i := 1; i < len(out); i++ {
263			if !strings.HasPrefix(out[i], "-") {
264				out[i] = newTarget
265				return out
266			}
267		}
268		return out
269	}
