272	// It skips the subcommand (first arg) and any flags (args starting with "-"),
273	// returning the first positional argument, which is the remote for push/fetch/ls-remote.
274	func extractRemoteFromArgs(args []string) string {
275		if len(args) < 2 {
276			return ""
277		}
278		// Skip subcommand (e.g., "push", "fetch", "ls-remote").
279		for _, arg := range args[1:] {
280			if !strings.HasPrefix(arg, "-") {
281				return arg
282			}
283		}
284		return ""
285	}
