287	// appendCheckpointTokenEnv appends GIT_CONFIG_COUNT-based env vars to inject
288	// an Authorization header into git HTTP requests. The token is sent as a Basic
289	// credential with the format "x-access-token:<token>" (base64-encoded), which
290	// is compatible with GitHub's token authentication.
291	//
292	// Existing GIT_CONFIG_KEY_*/GIT_CONFIG_VALUE_* entries are preserved; the new
293	// http.extraHeader entry is appended at the next free index and
294	// GIT_CONFIG_COUNT is updated accordingly. This keeps caller-injected git
295	// config (e.g., safe.directory, custom CA settings) intact.
296	func appendCheckpointTokenEnv(baseEnv []string, token string) []string {
297		existingCount := 0
298		for _, e := range baseEnv {
299			rest, ok := strings.CutPrefix(e, "GIT_CONFIG_COUNT=")
300			if !ok {
301				continue
302			}
303			if n, err := strconv.Atoi(rest); err == nil && n > 0 {
304				existingCount = n
305			}
306		}
307	
308		// Strip the old GIT_CONFIG_COUNT entry (we'll emit a new one) but keep
309		// GIT_CONFIG_KEY_*/GIT_CONFIG_VALUE_* entries in place.
310		filtered := make([]string, 0, len(baseEnv)+3)
311		for _, e := range baseEnv {
312			if strings.HasPrefix(e, "GIT_CONFIG_COUNT=") {
313				continue
314			}
315			filtered = append(filtered, e)
316		}
317	
318		idx := existingCount
319		encoded := base64.StdEncoding.EncodeToString([]byte("x-access-token:" + token))
320		return append(filtered,
321			fmt.Sprintf("GIT_CONFIG_COUNT=%d", existingCount+1),
322			fmt.Sprintf("GIT_CONFIG_KEY_%d=http.extraHeader", idx),
323			fmt.Sprintf("GIT_CONFIG_VALUE_%d=Authorization: Basic %s", idx, encoded),
324		)
325	}
