327	// isValidToken returns false if the token contains control characters (bytes < 0x20
328	// or 0x7F). This prevents HTTP header injection via CR/LF or other control chars
329	// embedded in the token value.
330	func isValidToken(token string) bool {
331		for _, b := range []byte(token) {
332			if b < 0x20 || b == 0x7F {
333				return false
334			}
335		}
336		return true
337	}
