302			}
303			if n, err := strconv.Atoi(rest); err == nil && n > 0 {
304				existingCount = n
305			}
306		}
307	
308		// Strip the old GIT_CONFIG_COUNT entry (we'll emit a new one) but keep
309		// GIT_CONFIG_KEY_*/GIT_CONFIG_VALUE_* entries in place.
310		filtered := make([]string, 0, len(baseEnv)+3)
311		for _, e := range baseEnv {
312			if strings.HasPrefix(e, "GIT_CONFIG_COUNT=") {
313				continue
314			}
315			filtered = append(filtered, e)
316		}
317	
318		idx := existingCount
319		encoded := base64.StdEncoding.EncodeToString([]byte("x-access-token:" + token))
320		return append(filtered,
321			fmt.Sprintf("GIT_CONFIG_COUNT=%d", existingCount+1),
322			fmt.Sprintf("GIT_CONFIG_KEY_%d=http.extraHeader", idx),
323			fmt.Sprintf("GIT_CONFIG_VALUE_%d=Authorization: Basic %s", idx, encoded),
324		)
